def _reserve_backup_link(path: str) -> str:
    """Hard-link the predecessor at a fresh, non-conflicting name.

    The random middle component keeps the name distinct from the fixed
    ``.old`` leftover and from concurrent transactions.  Each candidate
    comes from :func:`tempfile.mkstemp`, whose placeholder is removed
    again before the predecessor is linked onto the name; a failed
    reservation simply tries the next candidate.
    """
    directory = os.path.dirname(os.path.abspath(path))
    for _ in range(16):
        fd, name = tempfile.mkstemp(
            prefix=os.path.basename(path) + ".old-", dir=directory
        )
        os.close(fd)
        try:
            os.unlink(name)
        except FileNotFoundError:
            pass
        except OSError:
            continue
        try:
            os.link(path, name)
        except FileExistsError:
            continue
        return name
    raise OSError("could not reserve a non-conflicting transaction file name")

